// Deterministic, code-drawn sky. Only inserted after the player's explicit click.
export function observatorySky(){
  const stars=Array.from({length:100},(_,i)=>{const x=(i*173+31)%900,y=(i*i*29+17)%360,r=i%9===0?1.8:.7;return '<circle cx="'+x+'" cy="'+y+'" r="'+r+'" style="--twinkle:'+((i%7)+3)+'s;--delay:-'+(i%11)+'s"/>';}).join('');
  return '<svg class="observatory-sky" viewBox="0 0 900 500" aria-hidden="true"><defs><radialGradient id="night-glow"><stop stop-color="#354969"/><stop offset="1" stop-color="#0c1425"/></radialGradient><linearGradient id="observation-beam" x2="0" y2="1"><stop stop-color="#b5d6ef" stop-opacity="0"/><stop offset="1" stop-color="#b5d6ef" stop-opacity=".2"/></linearGradient></defs><rect width="900" height="500" fill="url(#night-glow)"/><g class="sky-stars" fill="#e9e9d9">'+stars+'</g><g class="sky-orbits" fill="none" stroke="#adc7d7" stroke-opacity=".12"><circle cx="450" cy="160" r="90"/><circle cx="450" cy="160" r="145"/><path d="M100 310Q450 -150 800 310"/></g><path class="sky-beam" d="M578 409L360 35L545 15Z" fill="url(#observation-beam)"/><g class="sky-constellation" fill="none" stroke="#d8dfb7" stroke-width="1.3"><path d="M335 153L389 114L447 144L479 83L545 120L508 192L447 144L418 215L335 153"/></g><g class="sky-new-stars" fill="#fff6cf">'+[[335,153],[389,114],[447,144],[479,83],[545,120],[508,192],[418,215]].map(([x,y])=>'<circle cx="'+x+'" cy="'+y+'" r="3"/>').join('')+'</g><path d="M0 423L130 350L240 410L340 369L460 428L640 337L780 399L900 359V500H0Z" fill="#101c2c"/><path d="M0 453Q250 392 460 449Q650 413 900 452V500H0Z" fill="#182331"/><g fill="#0a101b"><path d="M35 477V453L51 441L67 453V477H80V440L99 424L118 440V477H134V450L152 437L169 450V477Z"/><path d="M490 487V421H500V402A58 58 0 0 1 616 402V421H626V487Z"/><path d="M548 393L592 351L607 368L563 410Z"/><path d="M578 389L580 430H565V400Z"/></g><path d="M506 421H610M513 438H603M513 462H603" stroke="#87969b" stroke-opacity=".25"/><circle cx="602" cy="360" r="7" fill="#b9d9e5" class="sky-lens"/><path d="M0 487Q450 467 900 485V500H0Z" fill="#090f19"/></svg>';
}

export function observatoryAnimationHTML(){
  return '<div class="observatory-animation">'+observatorySky()+'<div class="observation-caption caption-first"><span>THE FIRST OBSERVATION</span><h2>A sky beyond your settlement</h2><p>From the first field to the stars.</p></div><div class="observation-caption caption-discovery"><span>GREAT OBSERVATORY COMPLETE</span><h2>A new perspective</h2><p>Your discoveries can guide the next civilization.</p></div><div class="observation-caption caption-future"><span>A GLIMPSE AHEAD · PLANNED CHAPTERS</span><h2>Beyond the horizon</h2><p>New eras. Distant shores. Civilizations still to come.</p></div></div><div class="observatory-footer"><span>The next civilization keeps your achievements and permanent upgrades.</span><button id="observation-summary">View run summary / skip</button></div>';
}
